def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_def_count = opp.count('D')
    my_def_count = my.count('D')

    if opp_def_count == 0:
        if n < 5:
            return 'C'
        if n >= 90:
            return 'D'
        if n % 2 == 1:
            return 'D'
        return 'C'

    recent = opp[-10:] if n >= 10 else opp
    recent_def = recent.count('D')

    if recent_def >= 6:
        return 'D'
    if recent_def >= 4:
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    last_opp = opp[-1]

    if n >= 95 and last_opp == 'D':
        return 'D'

    if last_opp == 'D':
        if opp_def_count > n * 0.3:
            return 'D'
        if rng.random() < 0.3:
            return 'D'
        return 'C'
    else:
        if my[-1] == 'D':
            return 'C'
        if n >= 95:
            return 'C'
        if opp_def_count <= 2 and n > 20 and rng.random() < 0.05:
            return 'D'
        return 'C'
